mapper.select:
SELECT  FROM student


        AND name LIKE CONCAT('%', #{name}, '%')


        AND gender = #{gender}


        AND major = #{major}


        AND stu_class = #{stuClass}


        AND score >= #{score}


        AND status = #{status}

